import{H as e,V as t,et as n,j as r}from"./chunks/framework.DKIRGhFK.js";import{$m as i,Am as a,Bm as o,Fm as s,Gm as c,Hm as l,Im as u,Jm as d,Km as f,Lm as p,Mm as m,Nm as h,Om as g,Pm as _,Qm as v,Rm as y,Um as b,Vm as x,Wm as S,Xm as C,Ym as w,Zm as T,eh as E,jm as D,km as O,nh as k,qm as A,th as j,zm as M}from"./chunks/assets.CUKu7Ix7.js";var N=JSON.parse(`{"title":"Linux常用命令","description":"","frontmatter":{},"headers":[],"relativePath":"java/deployment/linux/common-commands.md","filePath":"java/deployment/linux/common-commands.md"}`),P={name:`java/deployment/linux/common-commands.md`};function F(r,N,P,F,I,L){return n(),t(`div`,null,[...N[0]||=[e('<h1 id="linux常用命令" tabindex="-1">Linux常用命令 <a class="header-anchor" href="#linux常用命令" aria-label="Permalink to “Linux常用命令”">​</a></h1><h2 id="linux命令初体验" tabindex="-1">Linux命令初体验 <a class="header-anchor" href="#linux命令初体验" aria-label="Permalink to “Linux命令初体验”">​</a></h2><ul><li><p>Linux 命令格式：<code>command ``[``-options``] [``parameter``]</code></p></li><li><p>说明：</p><ul><li><p>command：命令名</p></li><li><p>[-options]：选项，可用来对命令进行控制，也可以省略 （可选）</p></li><li><p>[parameter]：参数，可以是零个、一个或多个（可选）</p></li></ul></li><li><p>例如：</p></li></ul><p><img src="'+k+'" alt="imagepng" width="1329" height="228"></p><p><strong>使用技巧：</strong></p><ul><li><p>Tab键自动补全</p></li><li><p>连续两次Tab键，给出操作提示</p></li><li><p>使用上下箭头快速调出曾经使用过的命令</p></li><li><p>使用clear命令或Ctrl+l快捷键实现清屏</p></li></ul><h2 id="目录操作命令" tabindex="-1">目录操作命令 <a class="header-anchor" href="#目录操作命令" aria-label="Permalink to “目录操作命令”">​</a></h2><h3 id="ls" tabindex="-1">ls <a class="header-anchor" href="#ls" aria-label="Permalink to “ls”">​</a></h3><ul><li><p>作用: 显示指定目录下的内容</p></li><li><p>语法: <code>ls [-al] ``[dir]</code></p></li><li><p>说明:</p></li></ul><p><code>-a</code> 显示所有文件及目录 (.\xA0开头的隐藏文件也会列出)</p><p><code>-l</code> 除文件名称外，同时将文件型态(d表示目录，-表示文件)、权限、拥有者、文件大小等信息详细列出</p><ul><li>注意:</li></ul><p>由于我们使用ls命令时经常需要加入-l选项，所以Linux为 <code>ls -l</code> 命令提供了一种简写方式，即 <code>ll</code></p><ul><li>常见用法:</li></ul><p><code>ls -al</code> 查看当前目录的所有文件及目录详细信息</p><p><code>ls -al /etc</code> 查看/etc目录下所有文件及目录详细信息</p><p><code>ll</code> 查看当前目录文件及目录的详细信息</p><p><strong>操作示例:</strong></p><p><img src="'+j+`" alt="imagepng" width="1401" height="396"></p><p><img src="`+E+`" alt="imagepng" width="1337" height="840"></p><p><img src="`+i+`" alt="imagepng" width="1338" height="274"></p><p><img src="`+v+`" alt="imagepng" width="1338" height="229"></p><h3 id="cd" tabindex="-1">cd <a class="header-anchor" href="#cd" aria-label="Permalink to “cd”">​</a></h3><ul><li><p>作用: 用于切换当前工作目录，即进入指定目录</p></li><li><p>语法: cd [dirName]</p></li><li><p>特殊说明:</p></li></ul><p>~ 表示用户的home目录</p><p>.\xA0 表示目前所在的目录</p><p>..\xA0 表示目前目录位置的上级目录</p><ul><li>举例:</li></ul><p>cd .. 切换到当前目录的上级目录</p><p>cd ~ 切换到用户的home目录</p><p>cd /usr/local 切换到/usr/local目录</p><ul><li>备注:</li></ul><p>用户的home目录</p><p>root用户 /root</p><p>其他用户 /home/xxx</p><p>**操作示例: **</p><p><img src="`+T+`" alt="imagepng" width="1338" height="442"></p><p><img src="`+C+`" alt="imagepng" width="1339" height="111"></p><p>cd .. 切换到当前目录位置的上级目录; 可以通过 cd ../.. 来切换到上级目录的上级目录。</p><h3 id="mkdir" tabindex="-1">mkdir <a class="header-anchor" href="#mkdir" aria-label="Permalink to “mkdir”">​</a></h3><ul><li><p>作用: 创建目录</p></li><li><p>语法: <code>mkdir [-p] dirName</code></p></li><li><p>说明:</p></li></ul><p>-p: 确保目录名称存在，不存在的就创建一个。通过此选项，可以实现多层目录同时创建</p><ul><li>举例:</li></ul><p>mkdir itcast 在当前目录下，建立一个名为itcast的子目录</p><p>mkdir -p itcast/test 在工作目录下的itcast目录中建立一个名为test的子目录，若itcast目录不存在，则建立一个</p><p><strong>操作演示:</strong></p><p><img src="`+w+`" alt="imagepng" width="1331" height="328"></p><h3 id="rm" tabindex="-1">rm <a class="header-anchor" href="#rm" aria-label="Permalink to “rm”">​</a></h3><ul><li><p>作用: 删除文件或者目录</p></li><li><p>语法: <code>rm [-rf] name</code></p></li><li><p>说明:</p></li></ul><p>-r: 将目录及目录中所有文件（目录）逐一删除，即递归删除</p><p>-f: 无需确认，直接删除</p><ul><li>举例:</li></ul><p><code>rm -r itcast/</code> 删除名为itcast的目录和目录中所有文件，删除前需确认</p><p><code>rm -rf itcast/</code> 无需确认，直接删除名为itcast的目录和目录中所有文件</p><p><code>rm -f hello.txt</code> 无需确认，直接删除hello.txt文件</p><p><strong>操作示例:</strong></p><p><img src="`+d+`" alt="imagepng" width="1341" height="180"></p><p>注意: 对于 <code>rm -rf xxx</code> 这样的指令，在执行的时候，一定要慎重，确认无误后再进行删除，避免误删。</p><h2 id="文件操作命令" tabindex="-1">文件操作命令 <a class="header-anchor" href="#文件操作命令" aria-label="Permalink to “文件操作命令”">​</a></h2><h3 id="cat" tabindex="-1">cat <a class="header-anchor" href="#cat" aria-label="Permalink to “cat”">​</a></h3><ul><li><p>作用: 用于显示文件内容</p></li><li><p>语法: <code>cat [-n] fileName</code></p></li><li><p>说明:</p></li></ul><p><code>-n</code>: 由1开始对所有输出的行数编号</p><ul><li>举例:</li></ul><p><code>cat /etc/profile</code> 查看/etc目录下的profile文件内容</p><p><strong>操作演示:</strong></p><p><img src="`+A+`" alt="imagepng" width="1342" height="396"></p><p>cat 指令会一次性查看文件的所有内容，如果文件内容比较多，这个时候查看起来就不是很方便了，这个时候我们可以通过一个新的指令more。</p><h3 id="more" tabindex="-1">more <a class="header-anchor" href="#more" aria-label="Permalink to “more”">​</a></h3><ul><li><p>作用: 以分页的形式显示文件内容</p></li><li><p>语法: <code>more fileName</code></p></li><li><p>操作说明:</p><ul><li><p>回车键 向下滚动一行</p></li><li><p>空格键 向下滚动一屏</p></li><li><p>b 返回上一屏</p></li><li><p>q或者Ctrl+C 退出more</p></li></ul></li><li><p>举例：</p><ul><li>more /etc/profile 以分页方式显示/etc目录下的profile文件内容</li></ul></li></ul><p>操作示例：</p><p><img src="`+f+'" alt="imagepng" width="1265" height="876"></p><p>当我们在查看一些比较大的文件时，我们可能需要经常查询文件尾部的数据信息，那这个时候如果文件很大，我们要一直向下翻页，直到最后一页，去看最新添加的数据，这种方式就比较繁琐了，此时，我们可以借助于tail指令。</p><h3 id="head" tabindex="-1">head <a class="header-anchor" href="#head" aria-label="Permalink to “head”">​</a></h3><ul><li><p>作用：查看文件开头的内容</p></li><li><p>语法：<code>head`` [``-n``] ``fileName</code></p></li><li><p>说明:</p><ul><li>-n ：输出文件开头的n行内容</li></ul></li><li><p>举例：</p><ul><li><p>head 1.log 默认显示1.log文件开头的10行内容</p></li><li><p>head -20 1.log 显示1.log文件开头的20行内容</p></li></ul></li></ul><h3 id="tail" tabindex="-1">tail <a class="header-anchor" href="#tail" aria-label="Permalink to “tail”">​</a></h3><ul><li><p>作用: 查看文件末尾的内容</p></li><li><p>语法: tail [-f] fileName</p></li><li><p>说明:</p></li></ul><p>-f : 动态读取文件末尾内容并显示，通常用于日志文件的内容输出</p><ul><li><p>举例:</p><ul><li><p>tail /etc/profile 显示/etc目录下的profile文件末尾10行的内容</p></li><li><p>tail -20 /etc/profile 显示/etc目录下的profile文件末尾20行的内容</p></li><li><p>tail -f /itcast/my.log 动态读取/itcast目录下的my.log文件末尾内容并显示</p></li></ul></li></ul><p><strong>操作示例：</strong></p><p>A. 默认查询文件尾部10行记录</p><p><img src="'+c+`" alt="imagepng" width="1335" height="295"></p><p>B. 可以通过指定参数设置查询尾部指定行数的数据</p><p><img src="`+S+`" alt="imagepng" width="1342" height="174"></p><p>C. 动态读取文件尾部的数据</p><p><img src="`+b+`" alt="imagepng" width="1339" height="223"></p><p>在窗口1中执行指令 <code>tail -f 1.txt</code> 动态查看文件尾部的数据。然后在顶部的标签中右键选择 &quot;复制标签&quot;，打开新的窗口2 , 此时再新打开的窗口2中执行指令 <code>echo 1 &gt;&gt; 1.txt</code> , 往1.txt文件尾部追加内容，然后我们就可以在窗口1中看到最新的文件尾部的数据。</p><p>如果我们不想查看文件尾部的数据了，可以直接使用快捷键 Ctrl+C ， 结束当前进程。</p><h2 id="拷贝移动命令" tabindex="-1">拷贝移动命令 <a class="header-anchor" href="#拷贝移动命令" aria-label="Permalink to “拷贝移动命令”">​</a></h2><h3 id="cp" tabindex="-1">cp <a class="header-anchor" href="#cp" aria-label="Permalink to “cp”">​</a></h3><ul><li><p>作用: 用于复制文件或目录</p></li><li><p>语法: cp [-r] source dest</p></li><li><p>说明:</p></li></ul><p>-r: 如果复制的是目录需要使用此选项，此时将复制该目录下所有的子目录和文件</p><ul><li>举例:</li></ul><p>cp hello.txt itcast/ 将hello.txt复制到itcast目录中</p><p>cp hello.txt ./hi.txt 将hello.txt复制到当前目录，并改名为hi.txt</p><p>cp -r itcast/ ./itheima/ 将itcast目录和目录下所有文件复制到itheima目录下</p><p>cp -r itcast/* ./itheima/ 将itcast目录下所有文件复制到itheima目录下</p><p><strong>操作示例:</strong></p><p><img src="`+l+`" alt="imagepng" width="1332" height="175"></p><p><img src="`+x+`" alt="imagepng" width="1337" height="292"></p><p><img src="`+o+`" alt="imagepng" width="1342" height="179"></p><p>如果拷贝的内容是目录，需要加上参数 -r</p><h3 id="mv" tabindex="-1">mv <a class="header-anchor" href="#mv" aria-label="Permalink to “mv”">​</a></h3><ul><li><p>作用: 为文件或目录改名、或将文件或目录移动到其它位置</p></li><li><p>语法: mv source dest</p></li><li><p>举例:</p><ul><li><p>mv hello.txt hi.txt 将hello.txt改名为hi.txt</p></li><li><p>mv hi.txt itheima/ 将文件hi.txt移动到itheima目录中</p></li><li><p>mv hi.txt itheima/hello.txt 将hi.txt移动到itheima目录中，并改名为hello.txt</p></li><li><p>mv itcast/ itheima/ 如果itheima目录不存在，将itcast目录改名为itheima</p></li><li><p>mv itcast/ itheima/ 如果itheima目录存在，将itcast目录移动到itheima目录中</p></li></ul></li></ul><p><strong>操作示例:</strong></p><p>mv 命令既能够改名，又可以移动，具体是改名还是移动,系统会根据我们输入的参数进行判定(如果第二个参数dest是一个已存在的目录,将执行移动操作,其他情况都是改名)</p><p><img src="`+M+'" alt="imagepng" width="1327" height="555"></p><h2 id="打包压缩命令" tabindex="-1">打包压缩命令 <a class="header-anchor" href="#打包压缩命令" aria-label="Permalink to “打包压缩命令”">​</a></h2><ul><li><p>作用: 对文件进行打包、解包、压缩、解压</p></li><li><p>语法: <code>tar [-zcxvf] ``fileName ``[files]</code></p><p>包文件后缀为.tar表示只是完成了打包，并没有压缩</p></li></ul><p>包文件后缀为.tar.gz表示打包的同时还进行了压缩</p><ul><li><p>说明:</p><ul><li><p>-z: z代表的是gzip，通过gzip命令处理文件，gzip可以对文件压缩或者解压</p></li><li><p>-c: c代表的是create，即创建新的包文件</p></li><li><p>-x: x代表的是extract，实现从包文件中还原文件</p></li><li><p>-v: v代表的是verbose，显示命令的执行过程</p></li><li><p>-f: f代表的是file，用于指定包文件的名称</p></li></ul></li><li><p>举例：</p><ul><li><p>打包</p><ul><li><p>tar -cvf hello.tar ./* 将当前目录下所有文件打包，打包后的文件名为hello.tar</p></li><li><p>tar -zcvf hello.tar.gz ./* 将当前目录下所有文件打包并压缩，打包后的文件名为hello.tar.gz</p></li></ul></li><li><p>解包</p><ul><li><p>tar -xvf hello.tar 将hello.tar文件进行解包，并将解包后的文件放在当前目录</p></li><li><p>tar -zxvf hello.tar.gz 将hello.tar.gz文件进行解压，并将解压后的文件放在当前目录</p></li><li><p>tar -zxvf hello.tar.gz -C /usr/local 将hello.tar.gz文件进行解压，并将解压后的文件放在/usr/local目录</p></li></ul></li></ul></li></ul><p><strong>操作示例:</strong></p><p>A. 打包</p><p><img src="'+y+`" alt="imagepng" width="1338" height="416"></p><p>B. 打包并压缩</p><p><img src="`+p+`" alt="imagepng" width="1338" height="412"></p><p>C. 解包</p><p><img src="`+u+`" alt="imagepng" width="1336" height="731"></p><p>D. 解压</p><p><img src="`+s+`" alt="imagepng" width="1339" height="247"></p><p>解压到指定目录,需要加上参数 -C</p><p><img src="`+_+`" alt="imagepng" width="1344" height="309"></p><h2 id="文本编辑命令" tabindex="-1">文本编辑命令 <a class="header-anchor" href="#文本编辑命令" aria-label="Permalink to “文本编辑命令”">​</a></h2><p>文本编辑的命令，主要包含两个: <code>vi</code> 和 <code>vim</code>，两个命令的用法类似，我们课程中主要讲解vim的使用。</p><h3 id="vi-amp-vim介绍" tabindex="-1">vi &amp; vim介绍 <a class="header-anchor" href="#vi-amp-vim介绍" aria-label="Permalink to “vi &amp;amp; vim介绍”">​</a></h3><ul><li><p>作用: vi命令是Linux系统提供的一个文本编辑工具，可以对文件内容进行编辑，类似于Windows中的记事本</p></li><li><p>语法: vi fileName</p></li><li><p>说明:</p><ul><li><p>1). vim是从vi发展来的一个功能更加强大的文本编辑工具，编辑文件时可以对文本内容进行着色，方便我们对文件进行编辑处理，所以实际工作中vim更加常用。</p></li><li><p>2). 要使用vim命令，需要我们自己完成安装。可以使用下面的命令来完成安装：<code>yum install vim</code></p></li></ul></li></ul><h3 id="vim安装" tabindex="-1">vim安装 <a class="header-anchor" href="#vim安装" aria-label="Permalink to “vim安装”">​</a></h3><p>命令： <code>yum install vim</code></p><p><img src="`+h+`" alt="imagepng" width="1335" height="272"></p><p>安装过程中，会有确认提示，此时输入 y，然后回车，继续安装：</p><p><img src="`+m+`" alt="imagepng" width="1342" height="204"></p><p><img src="`+D+`" alt="imagepng" width="1340" height="224"></p><h3 id="vim使用" tabindex="-1">vim使用 <a class="header-anchor" href="#vim使用" aria-label="Permalink to “vim使用”">​</a></h3><ul><li><p>作用: 对文件内容进行编辑，vim其实就是一个文本编辑器</p></li><li><p>语法: vim fileName</p></li><li><p>说明:</p><ul><li><p>1). 在使用vim命令编辑文件时，如果指定的文件存在则直接打开此文件。如果指定的文件不存在则新建文件。</p></li><li><p>2). vim在进行文本编辑时共分为三种模式，分别是 命令模式（Command mode），插入模式（Insert mode）和底行模式（Last line mode）。这三种模式之间可以相互切换。我们在使用vim时一定要注意我们当前所处的是哪种模式。</p></li></ul></li><li><p>三种模式:</p><ul><li><p>命令模式</p><ul><li><p>A. 命令模式下可以查看文件内容、移动光标（上下左右箭头、gg、G)</p></li><li><p>B. 通过vim命令打开文件后，默认进入命令模式</p></li><li><p>C. 另外两种模式需要首先进入命令模式，才能进入彼此</p></li></ul><table tabindex="0"><thead><tr><th><strong>命令模式指令</strong></th><th><strong>含义</strong></th></tr></thead><tbody><tr><td><strong>gg</strong></td><td>定位到文本内容的第一行</td></tr><tr><td><strong>G</strong></td><td>定位到文本内容的最后一行</td></tr><tr><td><strong>dd</strong></td><td>删除光标所在行的数据</td></tr><tr><td><strong>n****dd</strong></td><td>删除当前光标所在行及之后的n行数据</td></tr><tr><td><strong>u</strong></td><td>撤销操作</td></tr><tr><td>**i 或 a 或 o **</td><td>进入插入模式(进入后光标所处的位置不同而已)</td></tr></tbody></table></li><li><p>插入模式</p><ul><li><p>A. 插入模式下可以对文件内容进行编辑</p></li><li><p>B. 在命令模式下按下[i,a,o]任意一个，可以进入插入模式。进入插入模式后，下方会出现【insert】字样</p></li><li><p>C. 在插入模式下按下ESC键，回到命令模式</p></li></ul></li></ul></li><li><p>底行模式</p><ul><li><p>A. 底行模式下可以通过命令对文件内容进行查找、显示行号、退出等操作</p></li><li><p>B. 在命令模式下按下[:,/]任意一个，可以进入底行模式</p></li><li><p>C. 通过/方式进入底行模式后，可以对文件内容进行查找</p></li><li><p>D. 通过:方式进入底行模式后，可以输入wq（保存并退出）、q!（不保存退出）、set nu（显示行号）</p></li></ul><table tabindex="0"><thead><tr><th><strong>底行模式指令</strong></th><th><strong>含义</strong></th></tr></thead><tbody><tr><td><strong>:wq</strong></td><td>保存并退出</td></tr><tr><td><strong>:q!</strong></td><td>不保存退出</td></tr><tr><td>**:set **<strong>nu</strong></td><td>显示行号</td></tr><tr><td><strong>:set nonu</strong></td><td>取消行号显示</td></tr><tr><td><strong>:n</strong></td><td>定位到第n行，如 :10 就是定位到第10行</td></tr></tbody></table></li></ul><p><img src="`+a+'" alt="imagepng" width="905" height="479"></p><h2 id="查找命令" tabindex="-1">查找命令 <a class="header-anchor" href="#查找命令" aria-label="Permalink to “查找命令”">​</a></h2><h3 id="find" tabindex="-1">find <a class="header-anchor" href="#find" aria-label="Permalink to “find”">​</a></h3><ul><li><p>作用: 在指定目录下查找文件</p></li><li><p>语法: find dirName -option fileName</p></li><li><p>举例:</p><ul><li><p><code>find . ``–name`` &quot;*.java</code><em><code>&quot;</code>** 在当前目录及其子目录下查找.java结尾文件</em></p></li><li><p><code>find ``/itcast`` -name &quot;*.java&quot;</code> 在/itcast目录及其子目录下查找.java结尾的文件</p></li></ul></li></ul><p><strong>操作示例:</strong></p><p><img src="'+O+`" alt="imagepng" width="1341" height="233"></p><h3 id="grep" tabindex="-1">grep <a class="header-anchor" href="#grep" aria-label="Permalink to “grep”">​</a></h3><ul><li><p>作用: 从指定文件中查找指定的文本内容</p></li><li><p>语法: <code>grep word fileName</code></p></li><li><p>选项：</p><ul><li><p>-i: 检索的关键字忽略(ignore)大小写</p></li><li><p>-n: 显示关键字所在的这一行的行号</p></li><li><p>-A: 输出关键字所在行及之后(After)的几行记录 (如:-A5 表示输出关键字所在行之后的5行记录)</p></li><li><p>-B: 输出关键字所在行及之前(Before)的几行记录 (如:-B5 表示输出关键字所在行之前的5行记录)</p></li></ul></li><li><p>举例:</p><ul><li><p>grep Hello HelloWorld.java 查找HelloWorld.java文件中出现的Hello字符串的位置</p></li><li><p>grep hello *.java 查找当前目录中所有.java结尾的文件中包含hello字符串的位置</p></li></ul></li></ul><p><strong>操作示例:</strong></p><p><img src="`+g+`" alt="imagepng" width="1339" height="176"></p>`,143)]])}var I=r(P,[[`render`,F]]);export{N as __pageData,I as default};